node -e "
import { spawn } from 'child_process';

const server = spawn('npm', ['run', 'start', '--', '-p', '3001'], { stdio: 'inherit' });

async function run() {
  // wait for server
  for (let i = 0; i < 30; i++) {
    try {
      const res = await fetch('http://localhost:3001');
      if (res.ok) break;
    } catch (e) {
      await new Promise(r => setTimeout(r, 500));
    }
  }

  console.log('Testing / ...');
  const homeRes = await fetch('http://localhost:3001');
  const homeHtml = await homeRes.text();
  console.log('Home status:', homeRes.status, 'Has My Blog:', homeHtml.includes('My Blog'), 'Has Server-side rendered:', homeHtml.includes('Server-side rendered at:'));

  console.log('Testing /blog ...');
  const blogRes = await fetch('http://localhost:3001/blog');
  const blogHtml = await blogRes.text();
  console.log('Blog status:', blogRes.status, 'Has All Blog Posts:', blogHtml.includes('All Blog Posts'), 'Has Read More:', blogHtml.includes('Read More'));

  console.log('Testing /blog/1 ...');
  const blog1Res = await fetch('http://localhost:3001/blog/1');
  const blog1Html = await blog1Res.text();
  console.log('Blog 1 status:', blog1Res.status, 'Has Comments:', blog1Html.includes('Comments'), 'Has Back:', blog1Html.includes('Back'));

  console.log('Testing /blog/999999 (404) ...');
  const blog404Res = await fetch('http://localhost:3001/blog/999999');
  console.log('Blog 404 status:', blog404Res.status);

  console.log('Testing /api/posts GET ...');
  const apiRes = await fetch('http://localhost:3001/api/posts');
  const apiJson = await apiRes.json();
  console.log('API GET status:', apiRes.status, 'Posts:', apiJson.length);

  console.log('Testing /api/posts POST ...');
  const postRes = await fetch('http://localhost:3001/api/posts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'New', content: 'Content' })
  });
  const postJson = await postRes.json();
  console.log('API POST status:', postRes.status, 'Post created:', postJson.id, postJson.title);

  console.log('Testing /api/posts/1 GET ...');
  const api1Res = await fetch('http://localhost:3001/api/posts/1');
  const api1Json = await api1Res.json();
  console.log('API /1 status:', api1Res.status, api1Json);

  console.log('Testing /api/posts/1 PUT ...');
  const putRes = await fetch('http://localhost:3001/api/posts/1', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'Updated' })
  });
  const putJson = await putRes.json();
  console.log('API /1 PUT status:', putRes.status, putJson);

  console.log('Testing /api/posts/1 DELETE ...');
  const delRes = await fetch('http://localhost:3001/api/posts/1', {
    method: 'DELETE'
  });
  const delJson = await delRes.json();
  console.log('API /1 DELETE status:', delRes.status, delJson);

  server.kill('SIGTERM');
  process.exit(0);
}

run().catch(err => {
  console.error(err);
  server.kill('SIGTERM');
  process.exit(1);
});
"

