    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: 'Only content' })
  });
  console.log('POST /api/posts without title status:', res.status, await res.json());

  server.kill('SIGTERM');
}
run();
